<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$role = strtolower((string)($_SESSION['user_role'] ?? ''));
if (!in_array($role, ['teacher', 'admin'], true)) { http_response_code(403); exit('This dashboard is for teacher and administrator accounts.'); }
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
function th($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$name = (string)($_SESSION['user_name'] ?? 'Teacher');
$error = ''; $stats = ['assignments'=>0,'submitted'=>0,'pending'=>0,'overdue'=>0,'grading'=>0]; $recent=[];
try {
  $pdo = new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4','root','root',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
  // Ensure the assignment tables exist even if the create-assignment page has not been opened yet.
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, title VARCHAR(150) NOT NULL, instructions TEXT NULL, due_date DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (teacher_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignment_items (assignment_id BIGINT UNSIGNED NOT NULL, kanji_id INT NOT NULL, PRIMARY KEY (assignment_id,kanji_id), INDEX (kanji_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignment_students (assignment_id BIGINT UNSIGNED NOT NULL, student_id INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', submitted_at DATETIME NULL, UNIQUE KEY uq_tkas (assignment_id,student_id), INDEX (student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  // Keep dashboard compatible with older installations that predate grading.
  $studentColumns = $pdo->query('SHOW COLUMNS FROM teacher_kanji_assignment_students')->fetchAll(PDO::FETCH_COLUMN);
  if (!in_array('grade', $studentColumns, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN grade TINYINT UNSIGNED NULL');
  if (!in_array('teacher_feedback', $studentColumns, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN teacher_feedback TEXT NULL');
  if (!in_array('graded_at', $studentColumns, true)) $pdo->exec('ALTER TABLE teacher_kanji_assignment_students ADD COLUMN graded_at DATETIME NULL');
  $isAdmin = $role === 'admin';
  $where = $isAdmin ? '' : ' WHERE a.teacher_id = ?';
  $stmt = $pdo->prepare('SELECT COUNT(*) FROM teacher_kanji_assignments a'.$where);
  $stmt->execute($isAdmin ? [] : [(int)$_SESSION['user_id']]); $stats['assignments']=(int)$stmt->fetchColumn();
  $joinWhere = $isAdmin ? '' : ' WHERE a.teacher_id = ?';
  $stmt=$pdo->prepare("SELECT SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted, SUM(CASE WHEN s.status IS NULL OR s.status<>'submitted' THEN 1 ELSE 0 END) pending FROM teacher_kanji_assignments a LEFT JOIN teacher_kanji_assignment_students s ON s.assignment_id=a.id".$joinWhere);
  $stmt->execute($isAdmin ? [] : [(int)$_SESSION['user_id']]); $counts=$stmt->fetch() ?: [];
  $stats['submitted']=(int)($counts['submitted']??0); $stats['pending']=(int)($counts['pending']??0);
  $overdueSql = "SELECT COUNT(*) FROM teacher_kanji_assignment_students s JOIN teacher_kanji_assignments a ON a.id=s.assignment_id WHERE a.due_date IS NOT NULL AND a.due_date<CURDATE() AND s.status<>'submitted'".($isAdmin?'':' AND a.teacher_id=?');
  $stmt=$pdo->prepare($overdueSql); $stmt->execute($isAdmin?[]:[(int)$_SESSION['user_id']]); $stats['overdue']=(int)$stmt->fetchColumn();
  $gradingSql = "SELECT COUNT(*) FROM teacher_kanji_assignment_students s JOIN teacher_kanji_assignments a ON a.id=s.assignment_id WHERE s.status='submitted' AND s.grade IS NULL AND (s.teacher_feedback IS NULL OR s.teacher_feedback='')".($isAdmin?'':' AND a.teacher_id=?');
  $stmt=$pdo->prepare($gradingSql); $stmt->execute($isAdmin?[]:[(int)$_SESSION['user_id']]); $stats['grading']=(int)$stmt->fetchColumn();
  $stmt=$pdo->prepare("SELECT a.id,a.title,a.due_date,a.created_at,COUNT(DISTINCT i.kanji_id) kanji_count,COUNT(DISTINCT s.student_id) student_count,SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted_count,SUM(CASE WHEN s.status='submitted' AND s.grade IS NULL AND (s.teacher_feedback IS NULL OR s.teacher_feedback='') THEN 1 ELSE 0 END) grading_count,SUM(CASE WHEN s.status<>'submitted' AND a.due_date IS NOT NULL AND a.due_date<CURDATE() THEN 1 ELSE 0 END) overdue_count FROM teacher_kanji_assignments a LEFT JOIN teacher_kanji_assignment_items i ON i.assignment_id=a.id LEFT JOIN teacher_kanji_assignment_students s ON s.assignment_id=a.id".$where.' GROUP BY a.id,a.title,a.due_date,a.created_at ORDER BY a.created_at DESC LIMIT 8');
  $stmt->execute($isAdmin ? [] : [(int)$_SESSION['user_id']]); $recent=$stmt->fetchAll();
} catch (Throwable $e) { error_log('Kanji Master teacher dashboard: '.$e->getMessage()); $error='Could not load dashboard data. Check that MAMP MySQL is running and the kanji_master database is available.'; }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Dashboard | Kanji Master</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f8fafc;font-family:Arial,Helvetica,sans-serif}a{color:#c7d2fe;text-decoration:none}a:hover{text-decoration:underline}header{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:18px clamp(16px,4vw,44px);background:#111827;border-bottom:1px solid #263247}.back-link{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border:1px solid #334155;border-radius:10px;background:#1f2937;color:#fff;font-size:24px;line-height:1;flex-shrink:0}.header-left{display:flex;align-items:center;gap:12px}.brand{font-weight:800;color:#fff}.brand span{color:#a5b4fc}.nav{display:flex;gap:8px;flex-wrap:wrap;font-size:14px;align-items:center}.nav a{display:inline-flex;align-items:center;padding:9px 12px;border:1px solid #334155;border-radius:10px;background:#151d31;color:#e2e8f0}.nav a:hover{background:#263247;text-decoration:none}.nav a.active{background:#a5b4fc;border-color:#a5b4fc;color:#111827;font-weight:800}main{width:min(1120px,92%);margin:34px auto 60px}.eyebrow{color:#a5b4fc;text-transform:uppercase;letter-spacing:2px;font-size:12px}.welcome{padding:25px;background:linear-gradient(120deg,#1b2544,#111827);border:1px solid #334155;border-radius:20px}h1{font-size:clamp(29px,4vw,42px);margin:9px 0}.muted{color:#cbd5e1;line-height:1.6}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:14px;margin:20px 0}.stat,.card{background:#151d31;border:1px solid #334155;border-radius:17px;padding:20px}.stat span{display:block;color:#cbd5e1;font-size:13px}.stat strong{display:block;font-size:30px;margin-top:8px}.stat-link{display:block;color:#f8fafc;text-decoration:none;transition:border-color .15s,transform .15s}.stat-link:hover{border-color:#a5b4fc;transform:translateY(-2px);text-decoration:none}.stat-link small{display:block;color:#a5b4fc;margin-top:8px;font-size:12px}.actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:15px;margin:20px 0}.card h2{margin:0 0 8px;font-size:19px}.card p{color:#cbd5e1;font-size:14px;line-height:1.55}.btn{display:inline-block;background:#a5b4fc;color:#111827;padding:11px 14px;border-radius:10px;font-weight:bold;margin-top:8px}.secondary{background:#263247;color:#e2e8f0}.notice{padding:13px;background:#7f1d1d44;border:1px solid #991b1b;border-radius:12px;color:#fecaca;margin:18px 0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:790px}th,td{text-align:left;padding:13px 10px;border-bottom:1px solid #334155;font-size:14px}th{color:#cbd5e1;font-size:12px;text-transform:uppercase;letter-spacing:.5px}.empty{color:#cbd5e1;padding:16px 0}@media(max-width:600px){header{align-items:flex-start}.nav{gap:10px}main{margin-top:20px}.stat,.card{padding:16px}}</style></head><body>
<header><div class="header-left"><a class="back-link" href="javascript:history.back()" onclick="if(history.length<=1){window.location.href='login.php';return false;}" aria-label="Go back" title="Go back">←</a><a class="brand" href="teacher_dashboard.php">字 <span>Kanji Master</span> · Teacher</a></div><nav class="nav"><a class="active" aria-current="page" href="teacher_dashboard.php">Dashboard</a><a href="create_assignment.php">Create assignment</a><a href="teacher_submissions.php">Review submissions</a><a href="progress.php">Student progress</a><a href="study_activity.php">Study activity</a><a href="logout.php">Log out ↗</a></nav></header>
<main><section class="welcome"><div class="eyebrow">Teacher workspace</div><h1>Welcome, <?=th($name)?>!</h1><p class="muted">Manage kanji assignments, check student completion, and keep learning activities organized from one place.</p><a class="btn" href="create_assignment.php">＋ Create an assignment</a> <a class="btn secondary" href="teacher_submissions.php">Review submissions</a></section>
<?php if($error!==''): ?><div class="notice"><?=th($error)?></div><?php endif; ?>
<section class="stats"><div class="stat"><span><?= $role==='admin'?'All assignments':'Your assignments' ?></span><strong><?=number_format($stats['assignments'])?></strong></div><a class="stat stat-link" href="teacher_submissions.php"><span>Submitted</span><strong><?=number_format($stats['submitted'])?></strong><small>Review student work →</small></a><a class="stat stat-link" href="teacher_submissions.php"><span>Awaiting submission</span><strong><?=number_format($stats['pending'])?></strong><small>Check pending work →</small></a><a class="stat stat-link" href="teacher_submissions.php"><span>Overdue work</span><strong><?=number_format($stats['overdue'])?></strong><small>Review overdue work →</small></a><a class="stat stat-link" href="teacher_submissions.php"><span>Awaiting grading</span><strong><?=number_format($stats['grading'])?></strong><small>Grade submitted work →</small></a></section>
<section class="actions"><article class="card"><h2>📝 Create assignments</h2><p>Choose kanji, select students, add instructions, and set a due date.</p><a class="btn" href="create_assignment.php">Open assignment creator</a></article><article class="card"><h2>📋 Review submissions</h2><p>Check which students have marked their assignments as submitted and which are still pending.</p><a class="btn" href="teacher_submissions.php">Open submission review</a></article></section>
<section class="actions"><article class="card"><h2>📈 Student progress</h2><p>Review each student's submission completion, grade average, overdue work, and recent activity.</p><a class="btn secondary" href="progress.php">Open student progress</a></article><article class="card"><h2>✍️ Study activity</h2><p>See saved kanji-writing attempts, daily practice frequency, and time spent practicing.</p><a class="btn secondary" href="study_activity.php">Open study activity</a></article></section>
<section class="card"><h2>Recent assignments</h2><?php if(!$recent): ?><p class="empty">No assignments yet. Create your first assignment to see it listed here.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Kanji</th><th>Students</th><th>Submitted</th><th>Awaiting grading</th><th>Overdue</th><th>Due date</th></tr></thead><tbody><?php foreach($recent as $a): ?><tr><td><?=th($a['title'])?></td><td><?=number_format((int)$a['kanji_count'])?></td><td><?=number_format((int)$a['student_count'])?></td><td><?=number_format((int)($a['submitted_count']??0))?> / <?=number_format((int)$a['student_count'])?></td><td><?=number_format((int)($a['grading_count']??0))?></td><td><?=number_format((int)($a['overdue_count']??0))?></td><td><?=!empty($a['due_date'])?th($a['due_date']):'—'?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</main></body></html>
